(4925097, 716519, 93756, '<td valign="top">I like the irony and imagine it was a challenging shot to pull off. Well-photographed. Different twist on the meaning of double take that I am not sure fits the challenge description.</td>', 'I like the irony and imagine it was a challenging shot to pull off. Well-photographed. Different twist on the meaning of double take that I am not sure fits the challenge description.', '2008-09-01 09:55:16.000000', NULL, 1),
(4925104, 716852, 93756, '<td valign="top">A little overprocessed. The green in the water is too sharpened but it balances the composition nicely.</td>', 'A little overprocessed. The green in the water is too sharpened but it balances the composition nicely.', '2008-09-01 09:57:01.000000', NULL, 1),
(4925113, 716867, 93756, '<td valign="top">A closer crop would have appealed more since the water isn''t very pretty. Nice detail and clarity on the pelicans.</td>', 'A closer crop would have appealed more since the water isn''t very pretty. Nice detail and clarity on the pelicans.', '2008-09-01 09:59:51.000000', NULL, 1),
(4925116, 716675, 93756, '<td valign="top">Terrific capture. Perfect white/black tones. Nitpick: the black at the top &amp; bottom could have been left off or maybe just made thinner. (For purposes of challenges, you don''t have to have the perfect 3/2 ratio like you do for printing.)</td>', 'Terrific capture. Perfect white/black tones. Nitpick: the black at the top & bottom could have been left off or maybe just made thinner. (For purposes of challenges, you don''t have to have the perfect 3/2 ratio like you do for printing.)', '2008-09-01 10:01:52.000000', NULL, 1),
(4925117, 716644, 93756, '<td valign="top">I''ve got a flower photo contest to enter and just might have to copy your idea. Very good and the best of the flower photos.</td>', 'I''ve got a flower photo contest to enter and just might have to copy your idea. Very good and the best of the flower photos.', '2008-09-01 10:02:12.000000', NULL, 1),
