(4925123, 713971, 93756, '<td valign="top">Love the leathery look of the leaf. Love the ''2''s in the water. Nitpick: wish the water drops were more rounded.</td>', 'Love the leathery look of the leaf. Love the ''2''s in the water. Nitpick: wish the water drops were more rounded.', '2008-09-01 10:03:52.000000', NULL, 1),
(4925126, 716565, 93756, '<td valign="top">Neat how you made the footprints look like they are in mid-air. I like the "glowy" affect. Nice composition. Maybe try high heels or more traditional looking cowboy boots? 7</td>', 'Neat how you made the footprints look like they are in mid-air. I like the "glowy" affect. Nice composition. Maybe try high heels or more traditional looking cowboy boots? 7', '2008-09-01 10:04:18.000000', NULL, 1),
