(4938029, 716713, 65234, '<td valign="top">Wonderfully emotive shot; their body language speaks volumes.</td>', 'Wonderfully emotive shot; their body language speaks volumes.', '2008-09-06 10:40:58.000000', NULL, 1),
(4938032, 716350, 65234, '<td valign="top">They''re even making a heart shape :-)</td>', 'They''re even making a heart shape :-)', '2008-09-06 10:42:36.000000', NULL, 1),
(4938040, 716428, 65234, '<td valign="top">Extraordinary moment to capture (assuming those are live critters)!  The color palette is terrific with the grass and the cat''s green eyes, and all else in gray and white.  DOF and perspective is perfect.  But ... the animals are not all that similar ... two gray mammals, I guess?  There are other shots that nicely capture two more obviously similar subjects so this isn''t getting my top score, but still, a very interesting shot.</td>', 'Extraordinary moment to capture (assuming those are live critters)!  The color palette is terrific with the grass and the cat''s green eyes, and all else in gray and white.  DOF and perspective is perfect.  But ... the animals are not all that similar ... two gray mammals, I guess?  There are other shots that nicely capture two more obviously similar subjects so this isn''t getting my top score, but still, a very interesting shot.', '2008-09-06 10:54:16.000000', NULL, 1),
(4938045, 717006, 65234, '<td valign="top">Great ears on those two!  Nice job considering it looks like you had to shoot through a lot of foreground foliage.  It came out kind of dreamy.</td>', 'Great ears on those two!  Nice job considering it looks like you had to shoot through a lot of foreground foliage.  It came out kind of dreamy.', '2008-09-06 10:55:47.000000', NULL, 1),
(4938047, 716666, 65234, '<td valign="top">How adorable!  And decidedly trouble ;-)  Background is a little busy; next time I''d crop closer or, better still, bring out a sheet or something to drape over the chair and deck rail to make a uniform background.</td>', 'How adorable!  And decidedly trouble ;-)  Background is a little busy; next time I''d crop closer or, better still, bring out a sheet or something to drape over the chair and deck rail to make a uniform background.', '2008-09-06 10:58:04.000000', NULL, 1),
(4938058, 716879, 65234, '<td valign="top">Awwww :-)  Very cute moment.</td>', 'Awwww :-)  Very cute moment.', '2008-09-06 11:03:51.000000', NULL, 1);
