(4938798, 716949, 47791, '<td valign="top">This is an absolutely bizarre image. I like it though. The dof and dark border make it.</td>', 'This is an absolutely bizarre image. I like it though. The dof and dark border make it.', '2008-09-06 19:14:14.000000', NULL, 1),
(4938800, 715328, 60658, '<td valign="top">Side job training ducks to pose?!  Like the set-up, visually interesting.  A little soft for my liking, but that may be what you are going for, take that accordingly. Also, background is a little dark, if it were lighter the green would contrast nicely with the orange bill, I think.</td>', 'Side job training ducks to pose?!  Like the set-up, visually interesting.  A little soft for my liking, but that may be what you are going for, take that accordingly. Also, background is a little dark, if it were lighter the green would contrast nicely with the orange bill, I think.', '2008-09-06 19:19:40.000000', NULL, 1),
(4938803, 716835, 60658, '<td valign="top">Very cute little one.  Vast amount of white space is a little too much for me and seems to be a little blown out - the glass piece to the right is difficult to make out.  Nice image.</td>', 'Very cute little one.  Vast amount of white space is a little too much for me and seems to be a little blown out - the glass piece to the right is difficult to make out.  Nice image.', '2008-09-06 19:28:12.000000', NULL, 1),
(4938805, 715552, 60658, '<td valign="top">Like the color and water droplets. A little dark for me though.</td>', 'Like the color and water droplets. A little dark for me though.', '2008-09-06 19:33:24.000000', NULL, 1),
(4938808, 716455, 60658, '<td valign="top">Cute.  Like the pink backdrop, ties the image together.  The OCD in me wants to wash the dirty one.  Posing the toys differently would have added some interest, but good shot overall.</td>', 'Cute.  Like the pink backdrop, ties the image together.  The OCD in me wants to wash the dirty one.  Posing the toys differently would have added some interest, but good shot overall.', '2008-09-06 19:36:45.000000', NULL, 1),
(4938814, 716235, 60658, '<td valign="top">Very creative!  Might be my favorite take on the challenge.  Don''t know if this will bother others, but I see the paintbrush and want to see the artist!  Color is a bit flat in the background.</td>', 'Very creative!  Might be my favorite take on the challenge.  Don''t know if this will bother others, but I see the paintbrush and want to see the artist!  Color is a bit flat in the background.', '2008-09-06 19:45:30.000000', NULL, 1),
