(4938823, 716360, 60658, '<td valign="top">Nice statutes.  Arrangement and DOF work well.  Reflection is a bit distracting for me, maybe a little more and a touch warmer so it''s more like the sun hitting the earth.</td>', 'Nice statutes.  Arrangement and DOF work well.  Reflection is a bit distracting for me, maybe a little more and a touch warmer so it''s more like the sun hitting the earth.', '2008-09-06 19:55:20.000000', NULL, 1),
(4938828, 715445, 60658, '<td valign="top">Technically a beautiful shot - great color, sharpness, exposure dead on.  Pose is weird for me.  Maybe because the girls look a little too young.</td>', 'Technically a beautiful shot - great color, sharpness, exposure dead on.  Pose is weird for me.  Maybe because the girls look a little too young.', '2008-09-06 19:57:55.000000', NULL, 1),
